architecture.h4_f:
संदेश = CBOR{v:1, पाठ, उत्तर_को, भेजा_पर}
ct = AES-GCM-256-एन्क्रिप्ट(k, nonce, msg, aad=room_id)
POST /एपीआई/कमरे/{आईडी}/संदेश {सिफरटेक्स्ट: हेक्स(सीटी), नॉन्स: हेक्स}

cryptoWire.h1_f:
पीटी = CBOR{v:1, पाठ, उत्तर_तो?, थ्रेड_आईडी?, उल्लेख?, sent_at}
ct = AES-GCM-256-एन्क्रिप्ट(room_key, nonce, pt, aad=hex(room_id))
तार = CBOR{
  वी: 1,
  सिफरटेक्स्ट: हेक्स(सीटी), // परिवर्तनीय लंबाई
  गैर: हेक्स(12 बी),
  प्रेषक_छद्म: हेक्स(16 बी),
  sent_at: unix_ms
}

cryptoWire.h5_f:
बाहरी = CBOR{
  स्रोत_नोड: हेक्स32,
  लक्ष्य_उपयोगकर्ता: int64,
  इनर_सिफरटेक्स्ट: बाइट्स,
  आंतरिक_नॉनसे: बाइट्स,
  sent_at: unix_ms
}
sig = Ed25519-साइन(source_priv, बाहरी)
POST /फेडरेशन/डिलीवर {लिफाफा: बाहरी, हस्ताक्षर: हेक्स64 }

auth.h1_f:
POST /एपीआई/प्रमाणीकरण/रजिस्टर
  { उपयोगकर्ता नाम, पासवर्ड, x25519_public_key, डिस्प्ले_नाम, फ़ोन?, ईमेल?, अवतार_इमोजी }

प्रतिक्रिया 201 बनाया गया:
  {एक्सेस_टोकन, रिफ्रेश_टोकन, यूजर_आईडी, यूजरनेम, ... }

auth.h3_f:
एक्सेस_टोकन पेलोड:
  { उप: यूजर_आईडी, जेटीआई: डिवाइस_आईडी, टाइप: "एक्सेस", एक्सपी: अभी + 15 मिनट }
रिफ्रेश_टोकन पेलोड:
  { उप: यूजर_आईडी, जेटीआई: डिवाइस_आईडी, टाइप: "रिफ्रेश", एक्सपी: अभी + 30 दिन }

HS256-.env से नोड के 64-बाइट रहस्य के साथ हस्ताक्षरित

auth.h4_f:
रजिस्टर_बेगिन(): चुनौती = रैंड(32)
                    विकल्प = { rp.id, user.id, pubKeyCredParams, चुनौती }
                    वापसी के विकल्प

रजिस्टर_फिनिश(सत्यापन):
  TPM / सिक्योर एन्क्लेव रूट CA के विरुद्ध सत्यापन सत्यापित करें
  स्टोर { क्रेडेंशियल_आईडी, पब्लिक_की, काउंटर: 0 }

auth.h7_f:
POST /api/प्रमाणीकरण/qr/begin
  → {नॉनस: 128-बिट हेक्स, टीटीएल: 60 }
QR पेलोड = { नॉन, यूजर_आईडी, सर्वर: "https://node.example" }

POST /एपीआई/प्रमाणीकरण/क्यूआर/सत्यापित करें {नॉनस }
  → नया उपकरण पंजीकृत; जेडब्ल्यूटी वापस आ गए।

rooms.h6_f:
प्रेषक_छद्म = HMAC-SHA256(कक्ष_छद्म_नमक, प्रेषक_आईडी)[:16] // 32 हेक्स
सिफरटेक्स्ट = AES-GCM-एन्क्रिप्ट (room_key, नॉन्स, CBOR_payload, aad=room_id)

फैन-आउट फ़्रेम: { प्रकार: "एम", कमरा, संदेश: {आईडी, सीटी, नॉन्स, प्रेषक_छद्म, भेजा_एट}}

files.h2_f:
init POST /api/files/resumable/init {फ़ाइल नाम, आकार, chunk_size_hint}
            ← {अपलोड_आईडी, चंक_साइज़}
खंड PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct बाइट्स>
            ← 204
अंतिम रूप दें POST /api/files/resumable/{upload_id}/अंतिम रूप दें {plain_blake3}
            ← 201 {फ़ाइल_आईडी, यूआरएल}
TTLअधूरे पर: 24 घंटे

